"""Open fb01 using original Chrome data; release only a verified idle old owner."""
import hashlib,os,subprocess,sys,tempfile,uuid
from pathlib import Path
SCRIPT=b'\xef\xbb\xbfparam([long]$StarterPid=0,[switch]$FunctionsOnly,[string]$Root=\'E:\\FB-AutoUpload\')\n$ErrorActionPreference=\'Stop\'\n[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false)\n$fbRoot=[IO.Path]::GetFullPath($Root).TrimEnd(\'\\\')\n$fbCompare=$fbRoot.Replace(\'/\',\'\\\')\n$fbProfile=Join-Path $fbRoot \'profiles\\fb01\'\n\nfunction Assert-Fb01Path([string]$Path) {\n $item=Get-Item -LiteralPath $Path -Force\n if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw (\'\xe8\xb7\xaf\xe5\xbe\x84\xe6\x98\xaf\xe9\x93\xbe\xe6\x8e\xa5\xef\xbc\x8c\xe4\xbf\x9d\xe7\x95\x99\xe5\x8e\x9f\xe6\x96\x87\xe4\xbb\xb6\xef\xbc\x9a\'+$Path)}\n}\nfunction Get-Fb01Owners {\n foreach($row in @(Get-CimInstance Win32_Process -Filter "Name=\'chrome.exe\'")){\n  $cmd=[string]$row.CommandLine\n  if($cmd -match \'(?i)(?:^|\\s)--type(?:=|\\s)\'){continue}\n  $m=[regex]::Match($cmd,\'(?i)(?:^|\\s)--user-data-dir(?:=|\\s+)(?:"([^"]+)"|([^\\s]+))\')\n  if(-not $m.Success){continue}\n  $actual=if($m.Groups[1].Success){$m.Groups[1].Value}else{$m.Groups[2].Value}\n  if([string]::Equals([IO.Path]::GetFullPath($actual).TrimEnd(\'\\\'),$fbProfile,[StringComparison]::OrdinalIgnoreCase)){$row}\n }\n}\nfunction Get-Fb01ProjectWorkers {\n $rows=@(Get-CimInstance Win32_Process -Filter "Name=\'python.exe\' OR Name=\'pythonw.exe\'")\n $lookup=@{};foreach($r in $rows){$lookup[[long]$r.ProcessId]=$r}\n $skip=New-Object \'Collections.Generic.HashSet[long]\'\n $node=$lookup[$StarterPid]\n if($node){\n  $ownArgs=([regex]::Match([string]$node.CommandLine,\'^\\s*(?:"[^"]*"|[^\\s]+)\\s+(.*)$\')).Groups[1].Value\n  [void]$skip.Add([long]$node.ProcessId)\n  for($i=0;$i -lt 6;$i++){\n   $parent=$lookup[[long]$node.ParentProcessId]\n   if(-not $parent -or -not $ownArgs -or $parent.CreationDate -gt $node.CreationDate){break}\n   $args=([regex]::Match([string]$parent.CommandLine,\'^\\s*(?:"[^"]*"|[^\\s]+)\\s+(.*)$\')).Groups[1].Value\n   if($args -ne $ownArgs -or -not $skip.Add([long]$parent.ProcessId)){break}\n   $node=$parent\n  }\n }\n foreach($r in $rows){\n  if($skip.Contains([long]$r.ProcessId)){continue}\n  if(-not $r.CommandLine -and -not $r.ExecutablePath){throw \'\xe6\x9c\x89Python\xe8\xbf\x9b\xe7\xa8\x8b\xe6\x97\xa0\xe6\xb3\x95\xe6\xa0\xb8\xe5\xaf\xb9\xef\xbc\x8c\xe4\xbf\x9d\xe7\x95\x99fb01\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe3\x80\x82\'}\n  if(([string]$r.CommandLine).Replace(\'/\',\'\\\').IndexOf($fbCompare,[StringComparison]::OrdinalIgnoreCase) -ge 0 -or ([string]$r.ExecutablePath).Replace(\'/\',\'\\\').StartsWith($fbCompare+\'\\\',[StringComparison]::OrdinalIgnoreCase)){$r}\n }\n}\nfunction Get-Fb01ActiveRecords {\n $path=Join-Path $fbRoot \'logs\\publish_state.json\'\n if(-not(Test-Path -LiteralPath $path)){throw \'\xe5\x8f\x91\xe5\xb8\x83\xe8\xae\xb0\xe5\xbd\x95\xe7\xbc\xba\xe5\xa4\xb1\xef\xbc\x8c\xe6\x9c\xaa\xe5\x85\xb3\xe9\x97\xadfb01\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe3\x80\x82\'}\n Assert-Fb01Path $path\n for($i=0;$i -lt 3;$i++){\n  try{$value=Get-Content -LiteralPath $path -Raw -Encoding UTF8 | ConvertFrom-Json;break}\n  catch{if($i -eq 2){throw \'\xe5\x8f\x91\xe5\xb8\x83\xe8\xae\xb0\xe5\xbd\x95\xe6\xad\xa3\xe5\x9c\xa8\xe6\x9b\xb4\xe6\x96\xb0\xef\xbc\x8c\xe6\x9c\xaa\xe5\x85\xb3\xe9\x97\xad\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xef\xbc\x9b\xe7\xa8\x8d\xe5\x90\x8e\xe8\xbf\x90\xe8\xa1\x8c\xe5\x90\x8c\xe4\xb8\x80\xe5\x85\xa5\xe5\x8f\xa3\xe3\x80\x82\'};Start-Sleep -Milliseconds 200}\n }\n foreach($property in $value.PSObject.Properties){\n  $r=$property.Value\n  if($r.account -eq \'fb01\' -and $r.status -in @(\'preparing\',\'posting\')){$r}\n }\n}\nfunction Assert-Fb01StaleBrowser($Row) {\n $workers=@(Get-Fb01ProjectWorkers)\n if($workers.Count -and @(Get-Fb01ActiveRecords).Count){throw \'fb01\xe4\xbb\x8d\xe6\x9c\x89\xe5\x87\x86\xe5\xa4\x87\xe4\xb8\xad\xe6\x88\x96\xe6\x8f\x90\xe4\xba\xa4\xe4\xb8\xad\xe7\x9a\x84\xe5\x8f\x91\xe5\xb8\x83\xe8\xae\xb0\xe5\xbd\x95\xef\xbc\x8c\xe5\xbd\x93\xe5\x89\x8d\xe4\xbb\xbb\xe5\x8a\xa1\xe5\x8f\xaf\xe8\x83\xbd\xe4\xbd\xbf\xe7\x94\xa8\xe5\xae\x83\xef\xbc\x9b\xe6\x9c\xaa\xe7\xbb\x93\xe6\x9d\x9f\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xef\xbc\x8c\xe7\xad\x89\xe5\xbe\x85\xe8\xaf\xa5\xe8\xb4\xa6\xe5\x8f\xb7\xe5\xa4\x84\xe7\x90\x86\xe5\x90\x8e\xe5\x86\x8d\xe8\xaf\x95\xe3\x80\x82\'}\n foreach($worker in $workers){\n  if(-not $worker.CreationDate -or $worker.CreationDate.ToUniversalTime() -le $Row.CreationDate.ToUniversalTime()){\n   throw (\'\xe9\xa1\xb9\xe7\x9b\xae\xe4\xbb\xbb\xe5\x8a\xa1PID \'+$worker.ProcessId+\' \xe6\x97\xa9\xe4\xba\x8e\xe8\xaf\xa5\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe5\x90\xaf\xe5\x8a\xa8\xef\xbc\x8c\xe6\x97\xa0\xe6\xb3\x95\xe7\xa1\xae\xe8\xae\xa4fb01\xe5\xb7\xb2\xe7\xa9\xba\xe9\x97\xb2\xef\xbc\x9b\xe4\xbf\x9d\xe7\x95\x99\xe5\xbd\x93\xe5\x89\x8d\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe3\x80\x82\')\n  }\n }\n}\nfunction Get-Fb01PinnedProcess($Row) {\n $p=Get-Process -Id $Row.ProcessId\n try{\n  $null=$p.Handle\n  if($p.HasExited -or $p.ProcessName -ne \'chrome\' -or $p.StartTime.ToUniversalTime().ToString(\'yyyyMMddHHmmssfff\') -ne $Row.CreationDate.ToUniversalTime().ToString(\'yyyyMMddHHmmssfff\')){throw \'fb01\xe8\xbf\x9b\xe7\xa8\x8b\xe8\xba\xab\xe4\xbb\xbd\xe5\xb7\xb2\xe5\x8f\x98\xe5\x8c\x96\xef\xbc\x8c\xe6\x9c\xaa\xe5\x85\xb3\xe9\x97\xad\xe4\xbb\xbb\xe4\xbd\x95\xe7\xa8\x8b\xe5\xba\x8f\xe3\x80\x82\'}\n  return $p\n }catch{$p.Dispose();throw}\n}\nfunction Get-Fb01Action($Row,$Process) {\n if($Process.HasExited){throw \'fb01\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe5\xb7\xb2\xe9\x80\x80\xe5\x87\xba\xef\xbc\x8c\xe8\xaf\xb7\xe8\xbf\x90\xe8\xa1\x8c\xe5\x90\x8c\xe4\xb8\x80\xe5\x85\xa5\xe5\x8f\xa3\xe9\x87\x8d\xe6\x96\xb0\xe6\xa3\x80\xe6\x9f\xa5\xe3\x80\x82\'}\n if($Process.MainWindowHandle -ne 0){return \'restore\'}\n if([string]$Row.CommandLine -notmatch \'(?i)(?:^|\\s)--headless(?:=new|=old)?(?:\\s|$)\'){Assert-Fb01StaleBrowser $Row;return \'new_visible_window\'}\n Assert-Fb01StaleBrowser $Row\n return \'close_stale_headless\'\n}\nfunction Show-Fb01Window($Handle) {\n if(-not (\'Fb01OriginalWindow\' -as [type])){\n  Add-Type -TypeDefinition @\'\nusing System;\nusing System.Runtime.InteropServices;\npublic static class Fb01OriginalWindow {\n [DllImport("user32.dll")] public static extern bool ShowWindowAsync(IntPtr hwnd,int command);\n [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hwnd);\n}\n\'@\n }\n [void][Fb01OriginalWindow]::ShowWindowAsync($Handle,9)\n [void][Fb01OriginalWindow]::SetForegroundWindow($Handle)\n}\nfunction Invoke-Fb01Open {\n $mutex=$null;$owned=$false\n try{\n  foreach($path in @($fbRoot,(Join-Path $fbRoot \'profiles\'),$fbProfile,(Join-Path $fbProfile \'Default\'),(Join-Path $fbRoot \'upload_config.json\'))){Assert-Fb01Path $path}\n  $mutex=New-Object Threading.Mutex($false,\'Local\\FBUpload-fb01-original-window\')\n  try{$owned=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$owned=$true}\n  if(-not $owned){throw \'\xe5\xb7\xb2\xe6\x9c\x89fb01\xe6\x89\x93\xe5\xbc\x80\xe6\xa3\x80\xe6\x9f\xa5\xe5\x9c\xa8\xe8\xbf\x9b\xe8\xa1\x8c\xef\xbc\x8c\xe6\x9c\xaa\xe5\x86\x8d\xe6\x89\x93\xe5\xbc\x80\xe7\xac\xac\xe4\xba\x8c\xe4\xb8\xaa\xe7\xaa\x97\xe5\x8f\xa3\xe3\x80\x82\'}\n  $chrome=@(foreach($base in @($env:ProgramFiles,${env:ProgramFiles(x86)},$env:LOCALAPPDATA)){\n   if($base){$candidate=Join-Path $base \'Google\\Chrome\\Application\\chrome.exe\';if(Test-Path -LiteralPath $candidate -PathType Leaf){$candidate}}\n  }) | Select-Object -First 1\n  if(-not $chrome){throw \'\xe6\x9c\xaa\xe6\x89\xbe\xe5\x88\xb0\xe5\x8e\x9f\xe5\xb7\xb2\xe5\xae\x89\xe8\xa3\x85Google Chrome\xef\xbc\x8c\xe6\x9c\xaa\xe6\x9b\xb4\xe6\x8d\xa2\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe6\x88\x96\xe7\x99\xbb\xe5\xbd\x95\xe8\xb5\x84\xe6\x96\x99\xe3\x80\x82\'}\n  $owners=@(Get-Fb01Owners)\n  if($owners.Count -gt 1){throw \'fb01\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe7\x88\xb6\xe8\xbf\x9b\xe7\xa8\x8b\xe4\xb8\x8d\xe5\x94\xaf\xe4\xb8\x80\xef\xbc\x8c\xe6\x9c\xaa\xe7\xbb\x93\xe6\x9d\x9f\xe4\xbb\xbb\xe4\xbd\x95\xe7\xa8\x8b\xe5\xba\x8f\xe3\x80\x82\'}\n  if($owners.Count -eq 1){\n   $row=$owners[0];$p=Get-Fb01PinnedProcess $row\n   try{\n    $action=Get-Fb01Action $row $p\n    if($action -eq \'restore\'){Show-Fb01Window $p.MainWindowHandle;Write-Output \'fb01\xe5\xb7\xb2\xe6\x9c\x89\xe6\xad\xa3\xe5\xb8\xb8\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x8c\xe5\xb7\xb2\xe8\xbf\x98\xe5\x8e\x9f\xe5\x88\xb0\xe5\x89\x8d\xe5\x8f\xb0\xe3\x80\x82\';return}\n    if($action -eq \'close_stale_headless\'){\n     Assert-Fb01StaleBrowser $row\n     $fresh=@(Get-Fb01Owners)\n     if($fresh.Count -ne 1 -or $fresh[0].ProcessId -ne $row.ProcessId -or $fresh[0].CreationDate -ne $row.CreationDate -or $fresh[0].CommandLine -ne $row.CommandLine){throw \'fb01\xe5\x8d\xa0\xe7\x94\xa8\xe7\x8a\xb6\xe6\x80\x81\xe5\x8f\x98\xe5\x8c\x96\xef\xbc\x8c\xe4\xbf\x9d\xe7\x95\x99\xe7\x8e\xb0\xe6\x9c\x89\xe8\xbf\x9b\xe7\xa8\x8b\xe3\x80\x82\'}\n     $p.Refresh()\n     if($p.HasExited -or $p.MainWindowHandle -ne 0){throw \'fb01\xe7\xaa\x97\xe5\x8f\xa3\xe7\x8a\xb6\xe6\x80\x81\xe5\x8f\x98\xe5\x8c\x96\xef\xbc\x8c\xe6\x9c\xaa\xe7\xbb\x93\xe6\x9d\x9f\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe3\x80\x82\'}\n     $p.Kill()\n     if(-not $p.WaitForExit(10000)){throw \'\xe6\x97\xa7fb01\xe5\x90\x8e\xe5\x8f\xb0\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xe5\xb0\x9a\xe6\x9c\xaa\xe9\x80\x80\xe5\x87\xba\xef\xbc\x8c\xe6\x9c\xaa\xe9\x87\x8d\xe5\xa4\x8d\xe5\x90\xaf\xe5\x8a\xa8\xe3\x80\x82\'}\n     Write-Output (\'\xe5\xb7\xb2\xe9\x87\x8a\xe6\x94\xbe\xe7\xbb\x8f\xe6\xa0\xb8\xe9\xaa\x8c\xe7\x9a\x84fb01\xe6\x97\xa7\xe6\x97\xa0\xe7\xaa\x97\xe5\x8f\xa3\xe8\xbf\x9b\xe7\xa8\x8b\xef\xbc\x9a\'+$row.ProcessId)\n     if(@(Get-Fb01Owners).Count){throw \'fb01\xe8\xa2\xab\xe5\x85\xb6\xe4\xbb\x96\xe4\xbb\xbb\xe5\x8a\xa1\xe9\x87\x8d\xe6\x96\xb0\xe4\xbd\xbf\xe7\x94\xa8\xef\xbc\x8c\xe6\x9c\xaa\xe7\xbb\x93\xe6\x9d\x9f\xe6\x96\xb0\xe8\xbf\x9b\xe7\xa8\x8b\xe6\x88\x96\xe5\x86\x8d\xe5\xbc\x80\xe7\xaa\x97\xe5\x8f\xa3\xe3\x80\x82\'}\n    }\n   }finally{$p.Dispose()}\n  }\n  if(@(Get-Fb01ProjectWorkers).Count -and @(Get-Fb01ActiveRecords).Count){throw \'fb01\xe5\xbd\x93\xe5\x89\x8d\xe5\xad\x98\xe5\x9c\xa8\xe8\xbf\x9b\xe8\xa1\x8c\xe4\xb8\xad\xe7\x9a\x84\xe5\x8f\x91\xe5\xb8\x83\xef\xbc\x8c\xe4\xbf\x9d\xe7\x95\x99\xe5\x90\x8e\xe5\x8f\xb0\xe4\xbb\xbb\xe5\x8a\xa1\xef\xbc\x8c\xe6\x9c\xaa\xe5\x8f\xa6\xe5\xbc\x80\xe7\xaa\x97\xe5\x8f\xa3\xe3\x80\x82\'}\n  $start=New-Object Diagnostics.ProcessStartInfo\n  $start.FileName=$chrome;$start.WorkingDirectory=$fbRoot;$start.UseShellExecute=$false\n  $start.Arguments=\'--user-data-dir="\'+$fbProfile+\'" --profile-directory=Default --no-first-run --no-default-browser-check --new-window https://www.facebook.com/?locale=en_US\'\n  $started=[Diagnostics.Process]::Start($start)\n  try{\n   for($i=0;$i -lt 15;$i++){\n    foreach($row in @(Get-Fb01Owners)){\n     $p=Get-Fb01PinnedProcess $row\n     try{\n      $p.Refresh()\n      if(-not $p.HasExited -and $p.MainWindowHandle -ne 0){Show-Fb01Window $p.MainWindowHandle;Write-Output \'fb01\xe5\xb7\xb2\xe6\x89\x93\xe5\xbc\x80\xe6\xad\xa3\xe5\xb8\xb8Chrome\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x8c\xe6\xb2\xbf\xe7\x94\xa8\xe5\x8e\x9f\xe7\x99\xbb\xe5\xbd\x95\xe8\xb5\x84\xe6\x96\x99\xe3\x80\x81\xe6\x89\xa9\xe5\xb1\x95\xe5\x92\x8c\xe4\xbb\xa3\xe7\x90\x86\xe3\x80\x82\xe5\x85\xb6\xe4\xbb\x96\xe8\xb4\xa6\xe5\x8f\xb7\xe8\xbf\x9b\xe7\xa8\x8b\xe6\x9c\xaa\xe7\xbb\x93\xe6\x9d\x9f\xef\xbc\x8c\xe5\x8f\x91\xe5\xb8\x83\xe8\xae\xb0\xe5\xbd\x95\xe6\x9c\xaa\xe6\x94\xb9\xe5\x8a\xa8\xe3\x80\x82\';return}\n      if([string]$row.CommandLine -match \'(?i)(?:^|\\s)--headless(?:=new|=old)?(?:\\s|$)\'){throw \'fb01\xe5\x88\x9a\xe8\xa2\xab\xe5\x90\x8e\xe5\x8f\xb0\xe4\xbb\xbb\xe5\x8a\xa1\xe9\x87\x8d\xe6\x96\xb0\xe4\xbd\xbf\xe7\x94\xa8\xef\xbc\x8c\xe6\x9c\xaa\xe7\xbb\x93\xe6\x9d\x9f\xe5\xbd\x93\xe5\x89\x8d\xe5\x8f\x91\xe5\xb8\x83\xe6\xb5\x8f\xe8\xa7\x88\xe5\x99\xa8\xef\xbc\x9b\xe8\xaf\xb7\xe7\xa8\x8d\xe5\x90\x8e\xe9\x87\x8d\xe8\xaf\x95\xe3\x80\x82\'}\n     }finally{$p.Dispose()}\n    }\n    Start-Sleep -Seconds 1\n   }\n   throw \'\xe5\xb7\xb2\xe8\xaf\xb7\xe6\xb1\x82\xe6\x89\x93\xe5\xbc\x80\xe5\x8e\x9ffb01\xef\xbc\x8c\xe4\xbd\x86\xe5\xb0\x9a\xe6\x9c\xaa\xe7\xa1\xae\xe8\xae\xa4\xe5\x8f\xaf\xe8\xa7\x81\xe7\xaa\x97\xe5\x8f\xa3\xef\xbc\x9b\xe8\xb5\x84\xe6\x96\x99\xe5\x92\x8c\xe5\x8f\x91\xe5\xb8\x83\xe8\xae\xb0\xe5\xbd\x95\xe4\xbf\x9d\xe7\x95\x99\xef\xbc\x8c\xe8\xaf\xb7\xe5\x8f\x91\xe9\x80\x81\xe6\xad\xa4\xe8\xbe\x93\xe5\x87\xba\xe3\x80\x82\'\n  }finally{$started.Dispose()}\n }finally{\n  if($owned -and $mutex){$mutex.ReleaseMutex()}\n  if($mutex){$mutex.Dispose()}\n }\n}\nif(-not $FunctionsOnly){\n try{Invoke-Fb01Open}\n catch{Write-Output (\'STOP\xef\xbc\x9a\'+$_.Exception.Message);exit 1}\n}\n'
