def start(root):
    if sys.platform!='win32':raise ValueError('请在原Windows上传电脑运行。')
    root=Path(root).resolve()
    if not (root/'upload_config.json').is_file() or not (root/'profiles/fb01/Default').is_dir():raise ValueError('fb01原资料缺失，未创建替代资料。')
    if hashlib.sha256(SCRIPT).hexdigest()!=SCRIPT_SHA:raise ValueError('Checksum mismatch; stopped')
    folder=root/'material-staging/tools'/SCRIPT_SHA[:16]
    for path in (root/'material-staging',root/'material-staging/tools',folder):
        if path.is_symlink() or (hasattr(path,'is_junction') and path.is_junction()):raise ValueError('工具目录是链接。')
        path.mkdir(exist_ok=True)
    path=folder/'open_fb01_original_profile_20261124.ps1'
    if path.is_symlink():raise ValueError('工具文件是链接。')
    if path.exists():
        if path.read_bytes()!=SCRIPT:raise ValueError('同指纹工具已变化，未覆盖。')
    else:
        with tempfile.NamedTemporaryFile(dir=folder,delete=False) as handle:temp=Path(handle.name);handle.write(SCRIPT)
        try:temp.replace(path)
        finally:temp.unlink(missing_ok=True)
    print('仅检查并打开fb01原Chrome资料；当前发布若正在使用fb01则保留，不结束其他账号进程。',flush=True)
    log=folder/('fb01-open-'+uuid.uuid4().hex[:12]+'.log')
    with log.open('wb') as output:
        result=subprocess.run(['powershell.exe','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',str(path),'-Root',str(root),'-StarterPid',str(os.getpid())],stdin=subprocess.DEVNULL,stdout=output,stderr=subprocess.STDOUT,creationflags=0x08000200,timeout=90)
    data=log.read_bytes()
    if data:print(data.decode('utf-8-sig',errors='replace').strip(),flush=True)
    if result.returncode:print('检查记录：'+str(log),flush=True)
    return result.returncode

if __name__=='__main__':
    sys.stdout.reconfigure(encoding='utf-8',line_buffering=True)
    try:raise SystemExit(start(Path(sys.argv[1])))
    except Exception as error:print('STOP：',str(error) or type(error).__name__,flush=True);raise SystemExit(1)
